1	/* ============================================
2	   RENTAL SOLUTIONS - Enterprise IT Equipment Rental
3	   Premium B2B Website Stylesheet
4	   ============================================ */
5	
6	/* ---- CSS Variables ---- */
7	:root {
8	    /* Colors */
9	    --color-primary: #cc2326;
10	    --color-primary-light: #f2292d;
11	    --color-primary-dark: #a11c1f;
12	    --color-accent: #6c63ff;
13	    --color-accent-light: #8b85ff;
14	    --color-accent-dark: #4f46e5;
15	
16	    --color-bg-dark: #0c0634;
17	    --color-bg-dark-alt: #0d1326;
18	    --color-bg-light: #f8f9ff;
19	    --color-bg-lighter: #ffffff;
20	    --color-bg-gradient-dark: linear-gradient(135deg, #0d1b3e, #1f3c88, #0f172a);
21	
22	    --color-text-primary: #1d2433;
23	    --color-text-secondary: #4a5568;
24	    --color-text-muted: #6b7280;
25	    --color-text-light: #c8c8c8;
26	    --color-text-lighter: #cfcfcf;
27	    --color-text-white: #ffffff;
28	
29	    --color-border-light: #e5ecff;
30	    --color-border-muted: rgba(255, 255, 255, 0.12);
31	
32	    /* Typography */
33	    --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
34	    --fs-xs: 0.75rem;
35	    --fs-sm: 0.875rem;
36	    --fs-base: 1rem;
37	    --fs-md: 1.125rem;
38	    --fs-lg: 1.25rem;
39	    --fs-xl: 1.5rem;
40	    --fs-2xl: 2rem;
41	    --fs-3xl: 2.5rem;
42	    --fs-4xl: 3rem;
43	    --fs-5xl: 3.75rem;
44	
45	    --fw-light: 300;
46	    --fw-regular: 400;
47	    --fw-medium: 500;
48	    --fw-semibold: 600;
49	    --fw-bold: 700;
50	    --fw-black: 900;
51	
52	    --lh-tight: 1.2;
53	    --lh-normal: 1.5;
54	    --lh-relaxed: 1.7;
55	    --lh-loose: 1.9;
56	
57	    --ls-tight: -0.025em;
58	    --ls-normal: 0;
59	    --ls-wide: 0.05em;
60	    --ls-wider: 0.1em;
61	    --ls-widest: 0.2em;
62	
63	    /* Spacing */
64	    --space-1: 0.25rem;
65	    --space-2: 0.5rem;
66	    --space-3: 0.75rem;
67	    --space-4: 1rem;
68	    --space-5: 1.25rem;
69	    --space-6: 1.5rem;
70	    --space-7: 1.75rem;
71	    --space-8: 2rem;
72	    --space-10: 2.5rem;
73	    --space-12: 3rem;
74	    --space-16: 4rem;
75	    --space-20: 5rem;
76	    --space-24: 6rem;
77	
78	    /* Border Radius */
79	    --radius-sm: 8px;
80	    --radius-md: 12px;
81	    --radius-lg: 16px;
82	    --radius-xl: 20px;
83	    --radius-2xl: 22px;
84	    --radius-3xl: 30px;
85	    --radius-full: 50%;
86	
87	    /* Shadows */
88	    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.06);
89	    --shadow-md: 0 10px 30px rgba(0, 0, 0, 0.08);
90	    --shadow-lg: 0 15px 40px rgba(0, 0, 0, 0.1);
91	    --shadow-xl: 0 25px 50px rgba(0, 0, 0, 0.12);
92	    --shadow-accent: 0 12px 25px rgba(108, 99, 255, 0.25);
93	    --shadow-primary: 0 10px 25px rgba(204, 35, 38, 0.25);
94	
95	    /* Transitions */
96	    --transition-fast: 0.2s ease;
97	    --transition-base: 0.3s ease;
98	    --transition-slow: 0.5s ease;
99	    --transition-spring: 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
100	
101	    /* Container */
102	    --container-max: 1400px;
103	    --container-padding: 5%;
104	
105	    /* Header */
106	    --header-height: 80px;
107	}
108	
109	/* ---- Reset & Base ---- */
110	*,
111	*::before,
112	*::after {
113	    margin: 0;
114	    padding: 0;
115	    box-sizing: border-box;
116	}
117	
118	html {
119	    scroll-behavior: smooth;
120	    -webkit-text-size-adjust: 100%;
121	}
122	
123	body {
124	    font-family: var(--font-family);
125	    font-size: var(--fs-base);
126	    font-weight: var(--fw-regular);
127	    line-height: var(--lh-normal);
128	    color: var(--color-text-white);
129	    background: var(--color-bg-dark);
130	    overflow-x: hidden;
131	    -webkit-font-smoothing: antialiased;
132	    -moz-osx-font-smoothing: grayscale;
133	}
134	
135	img {
136	    max-width: 100%;
137	    height: auto;
138	    display: block;
139	}
140	
141	a {
142	    color: inherit;
143	    text-decoration: none;
144	    transition: color var(--transition-base);
145	}
146	
147	ul, ol {
148	    list-style: none;
149	}
150	
151	button {
152	    cursor: pointer;
153	    border: none;
154	    background: none;
155	    font-family: inherit;
156	    font-size: inherit;
157	}
158	
159	input, select, textarea {
160	    font-family: inherit;
161	    font-size: inherit;
162	}
163	
164	::selection {
165	    background: var(--color-primary);
166	    color: white;
167	}
168	
169	/* ---- Accessibility ---- */
170	.sr-only {
171	    position: absolute;
172	    width: 1px;
173	    height: 1px;
174	    padding: 0;
175	    margin: -1px;
176	    overflow: hidden;
177	    clip: rect(0, 0, 0, 0);
178	    white-space: nowrap;
179	    border: 0;
180	}
181	
182	.skip-link {
183	    position: fixed;
184	    top: -100%;
185	    left: var(--space-4);
186	    z-index: 10000;
187	    padding: var(--space-3) var(--space-6);
188	    background: var(--color-primary);
189	    color: white;
190	    font-weight: var(--fw-semibold);
191	    border-radius: 0 0 var(--radius-sm) var(--radius-sm);
192	    transition: top var(--transition-base);
193	}
194	
195	.skip-link:focus {
196	    top: 0;
197	}
198	
199	*:focus-visible {
200	    outline: 3px solid var(--color-accent);
201	    outline-offset: 2px;
202	}
203	
204	/* ---- Container ---- */
205	.container {
206	    width: 90%;
207	    max-width: var(--container-max);
208	    margin: 0 auto;
209	}
210	
211	/* ============================================
212	   HEADER / NAVIGATION
213	   ============================================ */
214	.site-header {
215	    position: fixed;
216	    top: 0;
217	    left: 0;
218	    width: 100%;
219	    z-index: 1000;
220	    padding: var(--space-4) 0;
221	    background: transparent;
222	    transition: background var(--transition-base), padding var(--transition-base), box-shadow var(--transition-base);
223	}
224	
225	.site-header.scrolled {
226	    background: rgba(12, 6, 52, 0.97);
227	    padding: var(--space-3) 0;
228	    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.3);
229	    backdrop-filter: blur(12px);
230	}
231	
232	.navbar {
233	    display: flex;
234	    justify-content: space-between;
235	    align-items: center;
236	}
237	
238	.logo {
239	    display: flex;
240	    align-items: center;
241	    gap: var(--space-3);
242	    text-decoration: none;
243	    flex-shrink: 0;
244	}
245	
246	.logo img {
247	    width: clamp(100px, 20vw, 160px);
248	    height: auto;
249	}
250	
251	.logo-text {
252	    display: flex;
253	    flex-direction: column;
254	}
255	
256	.logo-brand {
257	    font-size: var(--fs-xl);
258	    font-weight: var(--fw-bold);
259	    letter-spacing: var(--ls-wide);
260	    line-height: 1;
261	    color: var(--color-text-white);
262	}
263	
264	.logo-tagline {
265	    font-size: var(--fs-xs);
266	    color: rgba(255, 255, 255, 0.5);
267	    letter-spacing: var(--ls-wider);
268	    text-transform: uppercase;
269	}
270	
271	/* Navigation */
272	.main-nav {
273	    display: flex;
274	}
275	
276	.nav-list {
277	    display: flex;
278	    align-items: center;
279	    gap: var(--space-8);
280	}
281	
282	.nav-link {
283	    position: relative;
284	    font-size: var(--fs-sm);
285	    font-weight: var(--fw-medium);
286	    color: rgba(255, 255, 255, 0.8);
287	    letter-spacing: var(--ls-wide);
288	    transition: color var(--transition-base);
289	    padding: var(--space-2) 0;
290	}
291	
292	.nav-link::after {
293	    content: '';
294	    position: absolute;
295	    bottom: 0;
296	    left: 0;
297	    width: 0;
298	    height: 2px;
299	    background: var(--color-primary);
300	    transition: width var(--transition-base);
301	}
302	
303	.nav-link:hover,
304	.nav-link.active {
305	    color: var(--color-primary-light);
306	}
307	
308	.nav-link:hover::after,
309	.nav-link.active::after {
310	    width: 100%;
311	}
312	
313	/* Quote Button */
314	.quote-btn {
315	    display: inline-flex;
316	    align-items: center;
317	    gap: var(--space-2);
318	    padding: var(--space-3) var(--space-6);
319	    background: linear-gradient(90deg, var(--color-primary-light), var(--color-primary));
320	    color: white;
321	    font-size: var(--fs-sm);
322	    font-weight: var(--fw-semibold);
323	    border-radius: var(--radius-md);
324	    letter-spacing: var(--ls-wide);
325	    transition: transform var(--transition-base), box-shadow var(--transition-base);
326	    white-space: nowrap;
327	    flex-shrink: 0;
328	}
329	
330	.quote-btn:hover {
331	    transform: translateY(-2px);
332	    box-shadow: var(--shadow-primary);
333	}
334	
335	/* Mobile Menu Toggle */
336	.mobile-menu-toggle {
337	    display: none;
338	    flex-direction: column;
339	    justify-content: center;
340	    gap: 5px;
341	    width: 36px;
342	    height: 36px;
343	    padding: 6px;
344	    z-index: 1001;
345	}
346	
347	.hamburger-line {
348	    display: block;
349	    width: 100%;
350	    height: 2px;
351	    background: white;
352	    border-radius: 2px;
353	    transition: transform var(--transition-base), opacity var(--transition-base);
354	}
355	
356	.mobile-menu-toggle.active .hamburger-line:nth-child(1) {
357	    transform: translateY(7px) rotate(45deg);
358	}
359	
360	.mobile-menu-toggle.active .hamburger-line:nth-child(2) {
361	    opacity: 0;
362	}
363	
364	.mobile-menu-toggle.active .hamburger-line:nth-child(3) {
365	    transform: translateY(-7px) rotate(-45deg);
366	}
367	
368	/* ============================================
369	   HERO SLIDER
370	   ============================================ */
371	.hero-slider {
372	    position: relative;
373	    width: 100%;
374	    height: 90vh;
375	    min-height: 500px;
376	    max-height: 900px;
377	    overflow: hidden;
378	}
379	
380	.slide {
381	    position: absolute;
382	    inset: 0;
383	    opacity: 0;
384	    visibility: hidden;
385	    transition: opacity 0.8s ease, visibility 0.8s ease;
386	}
387	
388	.slide.active {
389	    opacity: 1;
390	    visibility: visible;
391	}
392	
393	.slide > img {
394	    width: 100%;
395	    height: 100%;
396	    object-fit: cover;
397	}
398	
399	.slide .content {
400	    position: absolute;
401	    top: 50%;
402	    left: var(--container-padding);
403	    transform: translateY(-50%);
404	    max-width: 650px;
405	    z-index: 10;
406	    animation: fadeInUp 1s ease forwards;
407	}
408	
409	.slide-title {
410	    font-size: clamp(2rem, 5vw, 3.75rem);
411	    font-weight: var(--fw-bold);
412	    line-height: var(--lh-tight);
413	    margin-bottom: var(--space-5);
414	    color: white;
415	}
416	
417	.highlight {
418	    color: var(--color-primary-light);
419	}
420	
421	.slide-desc {
422	    font-size: clamp(1rem, 2vw, 1.25rem);
423	    color: var(--color-text-light);
424	    line-height: var(--lh-relaxed);
425	    margin-bottom: var(--space-8);
426	    max-width: 500px;
427	}
428	
429	/* Slider Buttons */
430	.slider-btn {
431	    position: absolute;
432	    top: 50%;
433	    transform: translateY(-50%);
434	    width: 50px;
435	    height: 50px;
436	    border-radius: var(--radius-full);
437	    background: rgba(255, 255, 255, 0.15);
438	    backdrop-filter: blur(10px);
439	    color: white;
440	    font-size: var(--fs-lg);
441	    display: flex;
442	    align-items: center;
443	    justify-content: center;
444	    z-index: 20;
445	    transition: background var(--transition-base), transform var(--transition-base);
446	}
447	
448	.slider-btn:hover {
449	    background: rgba(255, 255, 255, 0.3);
450	    transform: translateY(-50%) scale(1.1);
451	}
452	
453	.prev { left: 20px; }
454	.next { right: 20px; }
455	
456	/* Dots */
457	.dots {
458	    position: absolute;
459	    bottom: 30px;
460	    left: 50%;
461	    transform: translateX(-50%);
462	    display: flex;
463	    gap: var(--space-3);
464	    z-index: 20;
465	}
466	
467	.dot {
468	    width: 12px;
469	    height: 12px;
470	    border-radius: var(--radius-full);
471	    background: rgba(255, 255, 255, 0.4);
472	    transition: background var(--transition-base), transform var(--transition-base);
473	}
474	
475	.dot.active {
476	    background: white;
477	    transform: scale(1.2);
478	}
479	
480	/* ============================================
481	   PARTNERS SECTION
482	   ============================================ */
483	.partners-section {
484	    padding: var(--space-12) 0;
485	    background: var(--color-bg-light);
486	    overflow: hidden;
487	}
488	
489	.section-title {
490	    text-align: center;
491	    font-size: var(--fs-2xl);
492	    font-weight: var(--fw-bold);
493	    color: var(--color-text-primary);
494	    margin-bottom: var(--space-8);
495	}
496	
497	.partners-slider {
498	    overflow: hidden;
499	    position: relative;
500	}
501	
502	.partners-track {
503	    display: flex;
504	    align-items: center;
505	    width: max-content;
506	    animation: scrollBrands 30s linear infinite;
507	}
508	
509	.partners-track img {
510	    width: 120px;
511	    height: 60px;
512	    object-fit: contain;
513	    margin: 0 var(--space-10);
514	    opacity: 0.6;
515	    transition: opacity var(--transition-base), transform var(--transition-base);
516	    filter: grayscale(100%);
517	}
518	
519	.partners-track img:hover {
520	    opacity: 1;
521	    transform: scale(1.1);
522	    filter: grayscale(0%);
523	}
524	
525	@keyframes scrollBrands {
526	    from { transform: translateX(0); }
527	    to { transform: translateX(-50%); }
528	}
529	
530	/* ============================================
531	   SECTION HEADINGS (Reusable)
532	   ============================================ */
533	.section-heading {
534	    text-align: center;
535	    max-width: 760px;
536	    margin: 0 auto var(--space-16);
537	}
538	
539	.section-badge {
540	    display: inline-block;
541	    padding: var(--space-2) var(--space-5);
542	    border-radius: var(--radius-3xl);
543	    background: #eef2ff;
544	    color: var(--color-accent);
545	    font-size: var(--fs-xs);
546	    font-weight: var(--fw-bold);
547	    letter-spacing: var(--ls-wider);
548	    text-transform: uppercase;
549	    margin-bottom: var(--space-4);
550	}
551	
552	.section-heading h2 {
553	    font-size: clamp(1.75rem, 4vw, 2.75rem);
554	    font-weight: var(--fw-bold);
555	    color: var(--color-text-primary);
556	    line-height: var(--lh-tight);
557	    margin-bottom: var(--space-5);
558	}
559	
560	.section-heading p {
561	    font-size: var(--fs-md);
562	    color: var(--color-text-muted);
563	    line-height: var(--lh-relaxed);
564	}
565	
566	/* ============================================
567	   SERVICES SECTION
568	   ============================================ */
569	.services-section {
570	    padding: var(--space-24) 0;
571	    background: var(--color-bg-light);
572	}
573	
574	.service-category {
575	    margin-bottom: var(--space-16);
576	}
577	
578	.category-title {
579	    font-size: var(--fs-xl);
580	    font-weight: var(--fw-bold);
581	    color: var(--color-text-primary);
582	    text-align: center;
583	    margin-bottom: var(--space-8);
584	}
585	
586	.services-grid {
587	    display: grid;
588	    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
589	    gap: var(--space-8);
590	}
591	
592	.service-card {
593	    background: var(--color-bg-lighter);
594	    padding: var(--space-10) var(--space-8);
595	    border-radius: var(--radius-xl);
596	    text-align: center;
597	    box-shadow: var(--shadow-sm);
598	    transition: transform var(--transition-spring), box-shadow var(--transition-base);
599	    position: relative;
600	    overflow: hidden;
601	    display: flex;
602	    flex-direction: column;
603	    align-items: center;
604	}
605	
606	.service-card::before {
607	    content: '';
608	    position: absolute;
609	    top: 0;
610	    left: 0;
611	    width: 100%;
612	    height: 4px;
613	    background: linear-gradient(90deg, var(--color-accent), var(--color-primary));
614	    transform: scaleX(0);
615	    transform-origin: left;
616	    transition: transform var(--transition-base);
617	}
618	
619	.service-card:hover {
620	    transform: translateY(-10px);
621	    box-shadow: var(--shadow-xl);
622	}
623	
624	.service-card:hover::before {
625	    transform: scaleX(1);
626	}
627	
628	.card-icon {
629	    width: 80px;
630	    height: 80px;
631	    margin: 0 auto var(--space-6);
632	    display: flex;
633	    align-items: center;
634	    justify-content: center;
635	    border-radius: var(--radius-full);
636	    background: linear-gradient(135deg, #eef2ff, #e0e7ff);
637	    color: var(--color-accent);
638	    font-size: var(--fs-2xl);
639	    transition: transform var(--transition-base), background var(--transition-base);
640	}
641	
642	.service-card:hover .card-icon {
643	    transform: scale(1.1) rotate(5deg);
644	    background: linear-gradient(135deg, var(--color-accent), var(--color-accent-dark));
645	    color: white;
646	}
647	
648	.service-card h4 {
649	    font-size: var(--fs-lg);
650	    font-weight: var(--fw-bold);
651	    color: var(--color-text-primary);
652	    margin-bottom: var(--space-3);
653	}
654	
655	.service-card p {
656	    color: var(--color-text-muted);
657	    line-height: var(--lh-relaxed);
658	    margin-bottom: var(--space-5);
659	    font-size: var(--fs-sm);
660	    flex: 1;
661	}
662	
663	.card-link {
664	    display: inline-flex;
665	    align-items: center;
666	    gap: var(--space-2);
667	    color: var(--color-accent);
668	    font-weight: var(--fw-semibold);
669	    font-size: var(--fs-sm);
670	    transition: gap var(--transition-base), color var(--transition-base);
671	}
672	
673	.card-link:hover {
674	    gap: var(--space-3);
675	    color: var(--color-accent-dark);
676	}
677	
678	/* ============================================
679	   STATISTICS SECTION
680	   ============================================ */
681	.stats-section {
682	    padding: var(--space-20) 0;
683	    background: var(--color-bg-dark);
684	    position: relative;
685	    overflow: hidden;
686	}
687	
688	.stats-section::before {
689	    content: '';
690	    position: absolute;
691	    width: 400px;
692	    height: 400px;
693	    background: rgba(108, 99, 255, 0.08);
694	    border-radius: var(--radius-full);
695	    top: -200px;
696	    left: -100px;
697	    filter: blur(60px);
698	}
699	
700	.stats-grid {
701	    display: grid;
702	    grid-template-columns: repeat(4, 1fr);
703	    gap: var(--space-8);
704	    text-align: center;
705	}
706	
707	.stat-item {
708	    padding: var(--space-8);
709	}
710	
711	.stat-number {
712	    font-size: clamp(2.5rem, 5vw, 3.5rem);
713	    font-weight: var(--fw-black);
714	    color: var(--color-text-white);
715	    line-height: 1;
716	    margin-bottom: var(--space-3);
717	    font-variant-numeric: tabular-nums;
718	}
719	
720	.stat-number::after {
721	    content: '+';
722	    font-size: 0.6em;
723	    color: var(--color-primary-light);
724	}
725	
726	.stat-label {
727	    font-size: var(--fs-sm);
728	    color: rgba(255, 255, 255, 0.6);
729	    text-transform: uppercase;
730	    letter-spacing: var(--ls-wider);
731	    font-weight: var(--fw-medium);
732	}
733	
734	/* ============================================
735	   WHY CHOOSE US SECTION
