/* ============================================
   RENTAL SOLUTIONS - Enterprise IT Equipment Rental
   Main JavaScript
   ============================================ */

(function() {
    'use strict';

    /* ---- DOM Ready ---- */
    document.addEventListener('DOMContentLoaded', function() {

        /* ============================================
           HERO SLIDER
           ============================================ */
        const slides = document.querySelectorAll('.slide');
        const dots = document.querySelectorAll('.dot');
        const prevBtn = document.querySelector('.slider-btn.prev');
        const nextBtn = document.querySelector('.slider-btn.next');
        let current = 0;
        let sliderInterval;

        function showSlide(index) {
            slides.forEach(function(slide) { slide.classList.remove('active'); });
            dots.forEach(function(dot) {
                dot.classList.remove('active');
                dot.setAttribute('aria-selected', 'false');
            });
            slides[index].classList.add('active');
            dots[index].classList.add('active');
            dots[index].setAttribute('aria-selected', 'true');
            current = index;
        }

        function nextSlide() {
            showSlide((current + 1) % slides.length);
        }

        function prevSlide() {
            showSlide((current - 1 + slides.length) % slides.length);
        }

        function startSlider() {
            sliderInterval = setInterval(nextSlide, 5000);
        }

        function resetSlider() {
            clearInterval(sliderInterval);
            startSlider();
        }

        if (nextBtn) {
            nextBtn.addEventListener('click', function() {
                nextSlide();
                resetSlider();
            });
        }

        if (prevBtn) {
            prevBtn.addEventListener('click', function() {
                prevSlide();
                resetSlider();
            });
        }

        // Dot navigation
        dots.forEach(function(dot) {
            dot.addEventListener('click', function() {
                var slideIndex = parseInt(this.getAttribute('data-slide'));
                showSlide(slideIndex);
                resetSlider();
            });
        });

        // Keyboard navigation for slider
        document.querySelector('.hero-slider').addEventListener('keydown', function(e) {
            if (e.key === 'ArrowLeft') { prevSlide(); resetSlider(); }
            if (e.key === 'ArrowRight') { nextSlide(); resetSlider(); }
        });

        startSlider();


        /* ============================================
           MOBILE MENU
           ============================================ */
        var menuToggle = document.getElementById('mobile-menu-toggle');
        var mainNav = document.getElementById('main-nav');

        if (menuToggle && mainNav) {
            // Create backdrop element
            var backdrop = document.createElement('div');
            backdrop.className = 'mobile-nav-backdrop';
            document.body.appendChild(backdrop);

            function closeMenu() {
                mainNav.classList.remove('open');
                menuToggle.classList.remove('active');
                menuToggle.setAttribute('aria-expanded', 'false');
                backdrop.classList.remove('visible');
                document.body.style.overflow = '';
            }

            function openMenu() {
                mainNav.classList.add('open');
                menuToggle.classList.add('active');
                menuToggle.setAttribute('aria-expanded', 'true');
                backdrop.classList.add('visible');
                document.body.style.overflow = 'hidden';
            }

            menuToggle.addEventListener('click', function() {
                if (mainNav.classList.contains('open')) {
                    closeMenu();
                } else {
                    openMenu();
                }
            });

            backdrop.addEventListener('click', closeMenu);

            // Close menu on nav link click
            var navLinks = mainNav.querySelectorAll('.nav-link');
            navLinks.forEach(function(link) {
                link.addEventListener('click', closeMenu);
            });

            // Close menu on outside click handled by backdrop

            // Close menu on Escape key
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && mainNav.classList.contains('open')) {
                    closeMenu();
                }
            });
        }


        /* ============================================
           STICKY HEADER
           ============================================ */
        var header = document.getElementById('site-header');

        function handleScroll() {
            if (window.scrollY > 50) {
                header.classList.add('scrolled');
            } else {
                header.classList.remove('scrolled');
            }
        }

        window.addEventListener('scroll', handleScroll, { passive: true });
        handleScroll();


        /* ============================================
           ACTIVE NAV LINK ON SCROLL
           ============================================ */
        var sections = document.querySelectorAll('section[id]');
        var navLinksAll = document.querySelectorAll('.nav-link');

        function updateActiveNav() {
            var scrollY = window.scrollY + 120;

            sections.forEach(function(section) {
                var sectionTop = section.offsetTop;
                var sectionHeight = section.offsetHeight;
                var sectionId = section.getAttribute('id');

                if (scrollY >= sectionTop && scrollY < sectionTop + sectionHeight) {
                    navLinksAll.forEach(function(link) {
                        link.classList.remove('active');
                        if (link.getAttribute('href') === '#' + sectionId) {
                            link.classList.add('active');
                        }
                    });
                }
            });
        }

        window.addEventListener('scroll', updateActiveNav, { passive: true });


        /* ============================================
           SCROLL ANIMATIONS (Intersection Observer)
           ============================================ */
        var fadeElements = document.querySelectorAll('.fade-in');

        if ('IntersectionObserver' in window) {
            var fadeObserver = new IntersectionObserver(function(entries) {
                entries.forEach(function(entry) {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                        fadeObserver.unobserve(entry.target);
                    }
                });
            }, {
                threshold: 0.15,
                rootMargin: '0px 0px -50px 0px'
            });

            fadeElements.forEach(function(el) {
                fadeObserver.observe(el);
            });
        } else {
            // Fallback: show all elements immediately
            fadeElements.forEach(function(el) {
                el.classList.add('visible');
            });
        }


        /* ============================================
           COUNTER ANIMATION
           ============================================ */
        var statNumbers = document.querySelectorAll('.stat-number[data-target]');

        function animateCounter(el) {
            var target = parseInt(el.getAttribute('data-target'));
            var duration = 2000;
            var startTime = null;

            function update(timestamp) {
                if (!startTime) startTime = timestamp;
                var progress = Math.min((timestamp - startTime) / duration, 1);
                // Ease out cubic
                var eased = 1 - Math.pow(1 - progress, 3);
                var current = Math.floor(eased * target);

                if (target >= 1000) {
                    el.textContent = current.toLocaleString();
                } else {
                    el.textContent = current;
                }

                if (progress < 1) {
                    requestAnimationFrame(update);
                } else {
                    if (target >= 1000) {
                        el.textContent = target.toLocaleString();
                    } else {
                        el.textContent = target;
                    }
                }
            }

            requestAnimationFrame(update);
        }

        if ('IntersectionObserver' in window && statNumbers.length > 0) {
            var counterObserver = new IntersectionObserver(function(entries) {
                entries.forEach(function(entry) {
                    if (entry.isIntersecting) {
                        animateCounter(entry.target);
                        counterObserver.unobserve(entry.target);
                    }
                });
            }, { threshold: 0.5 });

            statNumbers.forEach(function(num) {
                counterObserver.observe(num);
            });
        }


        /* ============================================
           BACK TO TOP BUTTON
           ============================================ */
        var backToTop = document.getElementById('back-to-top');

        if (backToTop) {
            window.addEventListener('scroll', function() {
                if (window.scrollY > 400) {
                    backToTop.classList.add('visible');
                } else {
                    backToTop.classList.remove('visible');
                }
            }, { passive: true });

            backToTop.addEventListener('click', function() {
                window.scrollTo({ top: 0, behavior: 'smooth' });
            });
        }


        /* ============================================
           SMOOTH SCROLL FOR ANCHOR LINKS
           ============================================ */
        document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
            anchor.addEventListener('click', function(e) {
                var targetId = this.getAttribute('href');
                if (targetId === '#') return;

                var targetEl = document.querySelector(targetId);
                if (targetEl) {
                    e.preventDefault();
                    var headerHeight = header ? header.offsetHeight : 0;
                    var targetPosition = targetEl.getBoundingClientRect().top + window.scrollY - headerHeight;

                    window.scrollTo({
                        top: targetPosition,
                        behavior: 'smooth'
                    });
                }
            });
        });


        /* ============================================
           CONTACT FORM HANDLING
           ============================================ */
        var contactForm = document.getElementById('contact-form');

        if (contactForm) {
            // Create message element
            var formMsg = document.createElement('div');
            formMsg.className = 'form-message';
            contactForm.insertBefore(formMsg, contactForm.firstChild);

            function showFormMessage(type, message) {
                formMsg.className = 'form-message ' + type;
                formMsg.textContent = message;
                formMsg.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }

            contactForm.addEventListener('submit', function(e) {
                e.preventDefault();

                var name = document.getElementById('name').value.trim();
                var company = document.getElementById('company').value.trim();
                var email = document.getElementById('email').value.trim();
                var phone = document.getElementById('phone').value.trim();

                // Simple validation
                if (!name || !company || !email || !phone) {
                    showFormMessage('error', 'Please fill in all required fields.');
                    return;
                }

                // Email validation
                var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                if (!emailRegex.test(email)) {
                    showFormMessage('error', 'Please enter a valid email address.');
                    return;
                }

                // Success message (since no backend)
                var submitBtn = contactForm.querySelector('.btn-submit');
                var originalText = submitBtn.innerHTML;
                submitBtn.innerHTML = '<i class="fa-solid fa-check"></i> Enquiry Sent!';
                submitBtn.style.background = '#10b981';
                submitBtn.disabled = true;

                showFormMessage('success', 'Thank you! Your enquiry has been submitted successfully. We will get back to you shortly.');

                setTimeout(function() {
                    submitBtn.innerHTML = originalText;
                    submitBtn.style.background = '';
                    submitBtn.disabled = false;
                    contactForm.reset();
                    formMsg.className = 'form-message';
                }, 4000);
            });
        }


        /* ============================================
           PARTNERS SLIDER - Pause on hover
           ============================================ */
        var partnersTrack = document.querySelector('.partners-track');
        if (partnersTrack) {
            partnersTrack.addEventListener('mouseenter', function() {
                this.style.animationPlayState = 'paused';
            });
            partnersTrack.addEventListener('mouseleave', function() {
                this.style.animationPlayState = 'running';
            });
        }

    });

})();
